-- Generated from api/migrations. Import into a new InfinityFree database with phpMyAdmin.
-- Do not import this over a database that already contains application tables.

CREATE TABLE admins (id INT UNSIGNED AUTO_INCREMENT NOT NULL, email VARCHAR(180) NOT NULL, password_hash VARCHAR(255) NOT NULL, name VARCHAR(120) NOT NULL, is_active TINYINT DEFAULT 1 NOT NULL, created_at DATETIME NOT NULL, UNIQUE INDEX uniq_admins_email (email), PRIMARY KEY (id));

CREATE TABLE admin_tokens (id INT UNSIGNED AUTO_INCREMENT NOT NULL, admin_id INT UNSIGNED NOT NULL, token_hash VARCHAR(64) NOT NULL, created_at DATETIME NOT NULL, expires_at DATETIME NOT NULL, last_used_at DATETIME DEFAULT NULL, UNIQUE INDEX uniq_admin_tokens_hash (token_hash), INDEX idx_admin_tokens_admin (admin_id), PRIMARY KEY (id));

CREATE TABLE contact_submissions (id INT UNSIGNED AUTO_INCREMENT NOT NULL, full_name VARCHAR(120) NOT NULL, email VARCHAR(180) NOT NULL, phone VARCHAR(32) NOT NULL, company VARCHAR(180) DEFAULT '' NOT NULL, designation VARCHAR(180) DEFAULT '' NOT NULL, project_type VARCHAR(80) NOT NULL, budget_range VARCHAR(80) DEFAULT '' NOT NULL, message LONGTEXT NOT NULL, country VARCHAR(80) DEFAULT '' NOT NULL, country_phone VARCHAR(16) DEFAULT '' NOT NULL, subject VARCHAR(200) DEFAULT '' NOT NULL, status VARCHAR(20) DEFAULT 'new' NOT NULL, ip_address VARCHAR(45) DEFAULT '' NOT NULL, user_agent VARCHAR(500) DEFAULT '' NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, deleted_at DATETIME DEFAULT NULL, INDEX idx_contact_submissions_status (status), INDEX idx_contact_submissions_created (created_at), INDEX idx_contact_submissions_ip (ip_address), PRIMARY KEY (id));

CREATE TABLE site_settings (id INT NOT NULL, email VARCHAR(180) NOT NULL, phone VARCHAR(32) NOT NULL, whatsapp_href VARCHAR(255) DEFAULT '' NOT NULL, location VARCHAR(120) DEFAULT '' NOT NULL, hours VARCHAR(120) DEFAULT '' NOT NULL, linkedin_url VARCHAR(255) DEFAULT '' NOT NULL, github_url VARCHAR(255) DEFAULT '' NOT NULL, x_url VARCHAR(255) DEFAULT '' NOT NULL, instagram_url VARCHAR(255) DEFAULT '' NOT NULL, facebook_url VARCHAR(255) DEFAULT '' NOT NULL, youtube_url VARCHAR(255) DEFAULT '' NOT NULL, seo_title VARCHAR(200) DEFAULT '' NOT NULL, seo_description VARCHAR(320) DEFAULT '' NOT NULL, og_image VARCHAR(255) DEFAULT '' NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY (id));

CREATE TABLE services (id INT UNSIGNED AUTO_INCREMENT NOT NULL, slug VARCHAR(120) NOT NULL, title VARCHAR(120) NOT NULL, description VARCHAR(500) NOT NULL, icon VARCHAR(40) DEFAULT 'code2' NOT NULL, image VARCHAR(255) DEFAULT '' NOT NULL, image_alt VARCHAR(255) DEFAULT '' NOT NULL, sort_order INT DEFAULT 0 NOT NULL, is_published TINYINT DEFAULT 1 NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE INDEX uniq_services_slug (slug), INDEX idx_services_sort (sort_order), PRIMARY KEY (id));

CREATE TABLE testimonials (id INT UNSIGNED AUTO_INCREMENT NOT NULL, author VARCHAR(120) NOT NULL, role VARCHAR(120) DEFAULT '' NOT NULL, company VARCHAR(160) DEFAULT '' NOT NULL, quote LONGTEXT NOT NULL, avatar VARCHAR(255) DEFAULT '' NOT NULL, rating INT DEFAULT 5 NOT NULL, sort_order INT DEFAULT 0 NOT NULL, is_published TINYINT DEFAULT 1 NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX idx_testimonials_sort (sort_order), PRIMARY KEY (id));

CREATE TABLE uploaded_files (id INT UNSIGNED AUTO_INCREMENT NOT NULL, relative_path VARCHAR(255) NOT NULL, original_filename VARCHAR(255) DEFAULT '' NOT NULL, mime_type VARCHAR(120) DEFAULT '' NOT NULL, size_bytes INT DEFAULT 0 NOT NULL, uploadable_type VARCHAR(40) DEFAULT '' NOT NULL, uploadable_id INT DEFAULT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX idx_uploaded_files_uploadable (uploadable_type, uploadable_id), INDEX idx_uploaded_files_created (created_at), PRIMARY KEY (id));

CREATE TABLE faq_entries (id INT UNSIGNED AUTO_INCREMENT NOT NULL, category VARCHAR(120) DEFAULT 'General' NOT NULL, question VARCHAR(500) NOT NULL, answer LONGTEXT NOT NULL, sort_order INT DEFAULT 0 NOT NULL, is_published TINYINT DEFAULT 1 NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX idx_faq_category_order (category, sort_order), PRIMARY KEY (id));

CREATE TABLE page_seo (path VARCHAR(255) NOT NULL, title VARCHAR(200) DEFAULT '' NOT NULL, description VARCHAR(320) DEFAULT '' NOT NULL, og_title VARCHAR(200) DEFAULT '' NOT NULL, og_description VARCHAR(320) DEFAULT '' NOT NULL, og_image VARCHAR(255) DEFAULT '' NOT NULL, updated_at DATETIME NOT NULL, PRIMARY KEY (path));

CREATE TABLE url_redirects (id INT UNSIGNED AUTO_INCREMENT NOT NULL, from_path VARCHAR(255) NOT NULL, to_path VARCHAR(255) NOT NULL, status_code INT DEFAULT 301 NOT NULL, created_at DATETIME NOT NULL, UNIQUE INDEX uniq_redirect_from_path (from_path), PRIMARY KEY (id));

CREATE TABLE admin_audit_log (id INT UNSIGNED AUTO_INCREMENT NOT NULL, admin_id INT DEFAULT NULL, admin_email VARCHAR(180) DEFAULT '' NOT NULL, method VARCHAR(10) NOT NULL, path VARCHAR(255) NOT NULL, status_code INT NOT NULL, created_at DATETIME NOT NULL, INDEX idx_admin_audit_created (created_at), PRIMARY KEY (id));

CREATE TABLE country_markets (id INT UNSIGNED AUTO_INCREMENT NOT NULL, name VARCHAR(100) NOT NULL, region VARCHAR(80) DEFAULT 'Other' NOT NULL, flag_image VARCHAR(255) NOT NULL, sort_order INT DEFAULT 0 NOT NULL, show_in_hero TINYINT DEFAULT 1 NOT NULL, show_in_coverage TINYINT DEFAULT 1 NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE INDEX uniq_country_markets_name (name), INDEX idx_country_markets_order (sort_order), PRIMARY KEY (id));

CREATE TABLE feedback_forms (id INT UNSIGNED AUTO_INCREMENT NOT NULL, author VARCHAR(120) NOT NULL, role VARCHAR(120) DEFAULT '' NOT NULL, company VARCHAR(160) DEFAULT '' NOT NULL, message LONGTEXT NOT NULL, avatar VARCHAR(255) DEFAULT '' NOT NULL, email VARCHAR(180) DEFAULT '' NOT NULL, rating SMALLINT DEFAULT 5 NOT NULL, service_title VARCHAR(120) DEFAULT '' NOT NULL, service_id INT DEFAULT NULL, source VARCHAR(40) DEFAULT 'services' NOT NULL, status VARCHAR(20) DEFAULT 'new' NOT NULL, reviewed_by INT DEFAULT NULL, reviewed_at DATETIME DEFAULT NULL, notes LONGTEXT NOT NULL, sort_order INT DEFAULT 0 NOT NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX idx_feedback_forms_status (status), INDEX idx_feedback_forms_created_at (created_at), INDEX idx_feedback_forms_service_id (service_id), PRIMARY KEY (id));

CREATE TABLE api_rate_limits (bucket_key VARCHAR(64) NOT NULL, window_started_at BIGINT NOT NULL, hit_count INT DEFAULT 0 NOT NULL, INDEX idx_api_rate_limits_window (window_started_at), PRIMARY KEY (bucket_key));

ALTER TABLE admin_tokens ADD CONSTRAINT fk_admin_tokens_admin FOREIGN KEY (admin_id) REFERENCES admins (id) ON DELETE CASCADE;

